/bin/bash -lc "python - <<'PY'
from collections import Counter
p='/tmp/codex_179.tsv'
with open(p) as f: lines=f.read().splitlines()
h=lines[1].split('\\t'); rows=[r.split('\\t') for r in lines[2:]]
idx={x:i for i,x in enumerate(h)}
for r in rows:
    try: v=float(r[idx['Variant Allele Freq']])
    except: continue
    if v<0.3:
        print('\\t'.join(r[i] for i in [idx['Chr:Pos'],idx['Zygosity'],idx['Inherited From'],idx['Variant Allele Freq'],idx['Sequence Ontology (Combined)'],idx['Classification']]))
PY"

